<template><ManagementShell><section class="grid gap-4"><header><p class="bm-kicker">Minha conta</p><h1 class="mt-2 font-display text-3xl font-black uppercase">Minhas compras</h1></header><article v-for="row in rows" :key="row.id" class="bm-panel flex flex-wrap items-center justify-between gap-3 rounded-md p-4"><div><strong>{{ row.productName }}</strong><p class="mt-1 text-xs text-white/45">{{ formatDate(row.createdAt) }}</p></div><div class="text-right"><strong class="text-ember">{{ row.price }} {{ row.currency }}</strong><p class="mt-1 text-xs text-white/55">{{ row.status }}</p></div></article><p v-if="!rows.length" class="bm-panel rounded-md p-8 text-center text-sm text-white/45">Você ainda não possui compras.</p></section></ManagementShell></template>
<script setup lang="ts">import type { CommercePurchase } from '~/composables/useCommerceApi'; const rows=ref<CommercePurchase[]>([]); const api=useCommerceApi(); onMounted(async()=>{try{rows.value=await api.listAccountPurchases()}catch{rows.value=[]}}); const formatDate=(v:string)=>new Intl.DateTimeFormat('pt-BR').format(new Date(v)); useSeoMeta({title:'Minhas compras'})</script>
